#!/usr/bin/perl
use strict; use warnings;
our $BIN="/workspace/dataset/test18_executable";
our @L=qw(scheme authority userinfo host port path query fragment
   has_scheme has_authority has_userinfo has_host has_port has_path
   has_query has_fragment to_string is_valid);

sub runbin {   # (arg, [extra args], {env})
  my ($arg,$extra,$env)=@_; $extra||=[]; 
  my @cmd=($BIN,$arg,@$extra);
  pipe(my $r, my $w) or die;
  my $pid=fork(); die "fork" unless defined $pid;
  if($pid==0){ close $r; open(STDOUT,">&",$w); open(STDERR,">","/dev/null");
     if($env){ for my $k (keys %$env){ if(defined $env->{$k}){$ENV{$k}=$env->{$k}} else {delete $ENV{$k}} } }
     exec {$cmd[0]} @cmd; exit 127; }
  close $w; local $/; my $out=<$r>; close $r; waitpid($pid,0); my $rc=$?>>8;
  $out='' unless defined $out;
  return ($rc,$out);
}
sub recs { my ($rc,$out)=runbin(@_); my @p=split(/\n/,$out,-1); pop @p if @p && $p[-1] eq ''; return ($rc,$out,\@p); }
sub esc { my $s=shift; $s='' unless defined $s;
  $s=~s/([^\x20-\x7e])/sprintf("\\x%02x",ord($1))/ge; return $s; }
sub joined { my ($rc,$out,$p)=recs(@_); return join("|",map{esc($_)}@$p); }
sub show { my ($lbl,$arg,$extra,$env)=@_;
  my ($rc,$out,$p)=recs($arg,$extra,$env);
  my $n=scalar @$p;
  printf("%-22s IN=%-34s rc=%d n=%-3d %s\n",$lbl,"'".esc($arg)."'",$rc,$n,
     $n==18 ? join("|",map{esc($_)}@$p) : "RAWBYTES=".esc($out));
  return ($rc,$out,$p);
}
sub fld { my ($arg)=@_; my ($rc,$out,$p)=recs($arg); return undef unless @$p==18;
  my %h; @h{@L}=@$p; return \%h; }
1;
PLEOF
cd /tmp/pr && perl -e 'require "/tmp/pr/h.pl"; show("sanity","http://www.example.com"); show("empty",""); show("noarg-check","x"); my($rc,$o)=runbin("x",[],undef); print "ok rc=$rc\n";'

