require "/tmp/pr/h.pl";

sub lcA { my $s=shift; $s =~ tr/A-Z/a-z/; return $s; }

sub parse_port {   # signed strtol semantics + [0,65535] range check
  my $t=shift; my $i=0; my $n=length($t);
  $i++ while $i<$n && substr($t,$i,1)=~/[ \t\n\013\014\r]/;
  my $neg=0;
  if($i<$n){ my $c=substr($t,$i,1); if($c eq "+"||$c eq "-"){ $neg=($c eq "-"); $i++; } }
  my $st=$i;
  $i++ while $i<$n && substr($t,$i,1)=~/[0-9]/;
  return -1 if $i==$st;                       # no digits -> invalid_argument
  my $ds=substr($t,$st,$i-$st); $ds=~s/^0+(?=\d)//;
  return -1 if length($ds)>10;                # > INT_MAX magnitude
  my $mag=0+$ds;
  return -1 if $mag>2147483647;
  my $v = $neg ? -$mag : $mag;
  return -1 if $v<0 || $v>65535;
  return $v;
}

sub model {   # returns list of 18 field strings
  my ($in)=@_;
  my ($scheme,$ui,$host,$port,$path,$query,$frag)=("","","",-1,"","","");
  my $s=$in;
  my $h=index($s,"#");  if($h>=0){ $frag=substr($s,$h+1);  $s=substr($s,0,$h); }
  my $q=index($s,"?");  if($q>=0){ $query=substr($s,$q+1); $s=substr($s,0,$q); }
  my $k=index($s,"://");
  if($k>=0){
    $scheme=lcA(substr($s,0,$k));
    my $rest=substr($s,$k+3);
    my $sl=index($rest,"/"); my $a;
    if($sl>=0){ $a=substr($rest,0,$sl); $path=substr($rest,$sl); } else { $a=$rest; }
    my $at=index($a,"@"); if($at>=0){ $ui=substr($a,0,$at); $a=substr($a,$at+1); }
    my $c=index($a,":");
    if($c>=0){ $host=substr($a,0,$c); $port=parse_port(substr($a,$c+1)); }
    else { $host=$a; }
  } else { $path=$s; }
  my $auth = (length($ui)?$ui."@":"").$host.($port!=-1 ? ":".$port : "");
  my $ts = (length($scheme)? $scheme."://".$auth : "").$path
         . (length($query)? "?".$query : "") . (length($frag)? "#".$frag : "");
  return ($scheme,$auth,$ui,$host,$port,$path,$query,$frag,
    length($scheme)?1:0, length($host)?1:0, length($ui)?1:0, length($host)?1:0,
    ($port!=-1)?1:0, length($path)?1:0, length($query)?1:0, length($frag)?1:0,
    $ts, (length($host)||length($path))?1:0);
}
sub expected { return join("\n",model(@_))."\n"; }
sub check { my $in=shift; my ($rc,$out)=runbin($in,[],undef);
  return ($out eq expected($in)) ? 1 : 0; }
1;
PLEOF
